import{_ as a,o as n,a as p,b as l}from"./app.C41L12d5.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C算子开发指南","link":"/guide/getting_started/ascend_c_overview_and_learning_path"},{"text":"编程指南","link":"/guide/programming_guide/document_structure"},{"text":"高级编程","link":"/guide/programming_guide/advanced_programming/advanced_programming"},{"text":"Aclnn算子工程化开发","link":"/guide/programming_guide/advanced_programming/aclnn_operator_development/overview"},{"text":"设计与实现","link":"/guide/programming_guide/advanced_programming/aclnn_operator_development/design_and_implementation/operator_function_design"},{"text":"核函数（Kernel）侧算子实现","link":"/guide/programming_guide/advanced_programming/aclnn_operator_development/design_and_implementation/kernel_operator_implementation"}]},"headers":[],"relativePath":"guide/programming_guide/advanced_programming/aclnn_operator_development/design_and_implementation/kernel_operator_implementation.md","filePath":"guide/programming_guide/advanced_programming/aclnn_operator_development/design_and_implementation/kernel_operator_implementation.md","outlineHeaders":[{"level":2,"title":"核函数（Kernel）格式","slug":"核函数（Kernel）格式","link":"#核函数（Kernel）格式"},{"level":3,"title":"命名规则","slug":"命名规则","link":"#命名规则"},{"level":3,"title":"函数形式","slug":"函数形式","link":"#函数形式"},{"level":3,"title":"参数顺序","slug":"参数顺序","link":"#参数顺序"},{"level":2,"title":"TilingData处理","slug":"TilingData处理","link":"#TilingData处理"},{"level":3,"title":"注册TilingData","slug":"注册TilingData","link":"#注册TilingData"},{"level":3,"title":"获取TilingData","slug":"获取TilingData","link":"#获取TilingData"},{"level":2,"title":"信息获取","slug":"信息获取","link":"#信息获取"},{"level":3,"title":"获取输入输出dtype和format","slug":"获取输入输出dtype和format","link":"#获取输入输出dtype和format"},{"level":2,"title":"相关文档","slug":"相关文档","link":"#相关文档"}],"lastUpdated":1787132575000}'),c={name:"guide/programming_guide/advanced_programming/aclnn_operator_development/design_and_implementation/kernel_operator_implementation.md"};function e(t,s,d,o,i,r){return n(),p("div",null,[...s[0]||(s[0]=[l(`<div><article class="markdown-body"><h1>基本流程</h1><p>本文属于基础内容，介绍aclnn工程化算子开发方式中核函数（Kernel）侧的基本接入流程，重点说明核函数（Kernel）入口函数格式、参数顺序、TilingData处理和编译期信息获取方式。Global Memory地址绑定、Unified Buffer（UB）管理、数据搬运、计算和同步等核函数（Kernel）核心实现方法，请参考<a href="../../../programming_model/ai_core_simd_programming/kernel_function.html">核函数（Kernel）</a>。</p><h2 id="核函数（Kernel）格式">核函数（Kernel）格式<a class="header-anchor" href="#核函数（Kernel）格式">​</a></h2><h3 id="命名规则">命名规则<a class="header-anchor" href="#命名规则">​</a></h3><p>核函数（Kernel）入口函数名需要和算子类型对应。算子类型采用大驼峰命名，核函数（Kernel）入口函数采用小写下划线命名，框架在编译和运行时根据命名规则完成匹配。</p><table><thead><tr><th>算子类型</th><th>核函数（Kernel）入口函数名</th></tr></thead><tbody><tr><td><code>AddCustom</code></td><td><code>add_custom</code></td></tr><tr><td><code>MatmulCustom</code></td><td><code>matmul_custom</code></td></tr><tr><td><code>ReduceMaxCustom</code></td><td><code>reduce_max_custom</code></td></tr><tr><td><code>Conv2DCustom</code></td><td><code>conv2_d_custom</code></td></tr><tr><td><code>GatherV2Custom</code></td><td><code>gather_v2_custom</code></td></tr></tbody></table><p>完整转换规则和更多示例会在<a href="../appendix/naming_conversion_table.html">命名转换规则对照表</a>中展开。</p><h3 id="函数形式">函数形式<a class="header-anchor" href="#函数形式">​</a></h3><p>核函数（Kernel）入口函数可以使用非模板入口或模板化入口。</p><p><strong>非模板入口</strong>使用<code>extern &quot;C&quot;</code>指定C语言链接规则，msOpGen生成的基础模板通常采用这种形式。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">extern</span><span class="w"> </span><span class="s">&quot;C&quot;</span><span class="w"> </span><span class="n">__global__</span><span class="w"> </span><span class="n">__aicore__</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">add_custom</span><span class="p">(</span><span class="n">GM_ADDR</span><span class="w"> </span><span class="n">x</span><span class="p">,</span><span class="w"> </span><span class="n">GM_ADDR</span><span class="w"> </span><span class="n">y</span><span class="p">,</span><span class="w"> </span><span class="n">GM_ADDR</span><span class="w"> </span><span class="n">z</span><span class="p">,</span><span class="w"> </span><span class="n">GM_ADDR</span><span class="w"> </span><span class="n">workspace</span><span class="p">,</span><span class="w"> </span><span class="n">GM_ADDR</span><span class="w"> </span><span class="n">tiling</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="c1">// 核函数具体内容</span>
<span class="w">    </span><span class="c1">// ...</span>
<span class="p">}</span>
</code></pre></div><p><strong>模板化入口</strong>通过模板参数承载dtype、Tile数量和分支选择信息。下面示例对应的算子类型是<code>AddCustomTemplate</code>，因此核函数（Kernel）入口名为<code>add_custom_template</code>。在aclnn工程化算子开发方式中，需要先声明模板参数及其可用组合，再由Host侧Tiling通过<code>ASCENDC_TPL_SEL_PARAM</code>选择组合，编译工具根据配置实例化对应的核函数（Kernel）。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="k">typename</span><span class="w"> </span><span class="nc">D_T_X</span><span class="p">,</span><span class="w"> </span><span class="k">typename</span><span class="w"> </span><span class="nc">D_T_Y</span><span class="p">,</span><span class="w"> </span><span class="k">typename</span><span class="w"> </span><span class="nc">D_T_Z</span><span class="p">,</span><span class="w"> </span><span class="kt">int</span><span class="w"> </span><span class="n">TILE_NUM</span><span class="p">,</span><span class="w"> </span><span class="kt">int</span><span class="w"> </span><span class="n">IS_SPLIT</span><span class="o">&gt;</span>
<span class="n">__global__</span><span class="w"> </span><span class="n">__aicore__</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">add_custom_template</span><span class="p">(</span><span class="n">GM_ADDR</span><span class="w"> </span><span class="n">x</span><span class="p">,</span><span class="w"> </span><span class="n">GM_ADDR</span><span class="w"> </span><span class="n">y</span><span class="p">,</span><span class="w"> </span><span class="n">GM_ADDR</span><span class="w"> </span><span class="n">z</span><span class="p">,</span>
<span class="w">                                               </span><span class="n">GM_ADDR</span><span class="w"> </span><span class="n">workspace</span><span class="p">,</span><span class="w"> </span><span class="n">GM_ADDR</span><span class="w"> </span><span class="n">tiling</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="c1">// 核函数具体内容</span>
<span class="w">    </span><span class="c1">// ...</span>
<span class="p">}</span>
</code></pre></div><p>上述代码使用<code>REGISTER_TILING_DEFAULT</code>注册默认TilingData结构体，并通过<code>GET_TILING_DATA_WITH_STRUCT</code>按指定类型解析Tiling数据。模板参数声明、Host侧选择和编译配置请参考<a href="./multi_branch_strategy.html">多分支策略</a>的Tiling模板编程章节。</p><h3 id="参数顺序">参数顺序<a class="header-anchor" href="#参数顺序">​</a></h3><p>核函数（Kernel）入口函数参数需要按照“输入、输出、workspace、tiling”的顺序排列。框架调用核函数（Kernel）时，会先按照算子原型定义中的输入输出顺序传入Tensor地址，再追加workspace和tiling两个参数。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">extern</span><span class="w"> </span><span class="s">&quot;C&quot;</span><span class="w"> </span><span class="n">__global__</span><span class="w"> </span><span class="n">__aicore__</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">add_custom</span><span class="p">(</span><span class="n">GM_ADDR</span><span class="w"> </span><span class="n">x</span><span class="p">,</span><span class="w"> </span><span class="n">GM_ADDR</span><span class="w"> </span><span class="n">y</span><span class="p">,</span><span class="w"> </span><span class="n">GM_ADDR</span><span class="w"> </span><span class="n">z</span><span class="p">,</span>
<span class="w">                                                  </span><span class="n">GM_ADDR</span><span class="w"> </span><span class="n">workspace</span><span class="p">,</span><span class="w"> </span><span class="n">GM_ADDR</span><span class="w"> </span><span class="n">tiling</span><span class="p">);</span>
</code></pre></div><p>参数含义如下：</p><table><thead><tr><th>参数</th><th>来源</th><th>作用</th></tr></thead><tbody><tr><td><code>x</code>、<code>y</code></td><td>算子原型中的输入</td><td>指向输入Tensor的Global Memory地址</td></tr><tr><td><code>z</code></td><td>算子原型中的输出</td><td>指向输出Tensor的Global Memory地址</td></tr><tr><td><code>workspace</code></td><td>框架追加</td><td>指向workspace内存地址</td></tr><tr><td><code>tiling</code></td><td>框架追加</td><td>指向Host侧Tiling写入的数据</td></tr></tbody></table><blockquote><p><strong>说明：输入输出同名场景</strong></p><p>如果算子原型中的输入和输出同名，msOpGen生成核函数（Kernel）入口参数时会给输出参数增加<code>ref</code>后缀，用于区分输入和输出地址。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">extern</span><span class="w"> </span><span class="s">&quot;C&quot;</span><span class="w"> </span><span class="n">__global__</span><span class="w"> </span><span class="n">__aicore__</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">add_custom</span><span class="p">(</span><span class="n">GM_ADDR</span><span class="w"> </span><span class="n">x</span><span class="p">,</span><span class="w"> </span><span class="n">GM_ADDR</span><span class="w"> </span><span class="n">y</span><span class="p">,</span>
<span class="w">                                                  </span><span class="n">GM_ADDR</span><span class="w"> </span><span class="n">x_ref</span><span class="p">,</span><span class="w"> </span><span class="n">GM_ADDR</span><span class="w"> </span><span class="n">workspace</span><span class="p">,</span>
<span class="w">                                                  </span><span class="n">GM_ADDR</span><span class="w"> </span><span class="n">tiling</span><span class="p">);</span>
</code></pre></div></blockquote><p>核函数（Kernel）实现类的内部组织方式由算子计算逻辑和Ascend C编程模式决定。在aclnn工程化算子开发方式中，核函数（Kernel）入口只需要保持框架要求的参数顺序，读取TilingData，并将输入输出地址和Tiling参数传给核函数（Kernel）实现类。</p><p>AddCustom的核函数（Kernel）入口按以下步骤串联算子实现：</p><ol><li>通过<code>GET_TILING_DATA</code>读取Host侧传入的<code>totalLength</code>和<code>tileNum</code>。</li><li>创建<code>KernelAdd</code>对象，将输入输出地址和Tiling参数传入<code>Init</code>。</li><li>调用<code>Process</code>，将当前Tile的输入数据从Global Memory搬运到Local Memory。</li><li>调用<code>Add</code>完成逐元素加法计算。</li><li>将计算结果从Local Memory搬运回Global Memory。</li></ol><p><code>Process</code>根据<code>tileNum</code>循环执行步骤3至步骤5，直到当前Block的所有Tile处理完成。搬运和计算之间需要根据数据依赖做好同步，具体实现请参考<a href="../../../programming_model/ai_core_simd_programming/kernel_function.html">核函数（Kernel）</a>。</p><h2 id="TilingData处理">TilingData处理<a class="header-anchor" href="#TilingData处理">​</a></h2><p>Host侧Tiling函数会把核函数（Kernel）运行需要的参数写入TilingData。TilingData可以使用标准C++语法或宏定义方式定义，两种方式的注册位置和注册接口不同。</p><h3 id="注册TilingData">注册TilingData<a class="header-anchor" href="#注册TilingData">​</a></h3><p>注册TilingData用于确定核函数（Kernel）默认使用的TilingData结构体类型。标准C++结构体和宏定义结构体的注册位置不同。</p><p><strong>标准C++结构体</strong></p><p>使用标准C++语法定义TilingData时，核函数（Kernel）侧在入口函数中使用<a href="../../../../../api/SIMD-API/basic_api/Kernel-Tiling/REGISTER_TILING_DEFAULT.html">REGISTER_TILING_DEFAULT</a>注册默认结构体。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">extern</span><span class="w"> </span><span class="s">&quot;C&quot;</span><span class="w"> </span><span class="n">__global__</span><span class="w"> </span><span class="n">__aicore__</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">add_custom</span><span class="p">(</span><span class="n">GM_ADDR</span><span class="w"> </span><span class="n">x</span><span class="p">,</span><span class="w"> </span><span class="n">GM_ADDR</span><span class="w"> </span><span class="n">y</span><span class="p">,</span><span class="w"> </span><span class="n">GM_ADDR</span><span class="w"> </span><span class="n">z</span><span class="p">,</span>
<span class="w">                                                  </span><span class="n">GM_ADDR</span><span class="w"> </span><span class="n">workspace</span><span class="p">,</span><span class="w"> </span><span class="n">GM_ADDR</span><span class="w"> </span><span class="n">tiling</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="n">REGISTER_TILING_DEFAULT</span><span class="p">(</span><span class="n">AddCustomTilingData</span><span class="p">);</span>
<span class="w">    </span><span class="c1">// ...</span>
<span class="p">}</span>
</code></pre></div><p><strong>宏定义结构体</strong></p><p>使用<code>BEGIN_TILING_DATA_DEF</code>等宏定义TilingData时，在Host侧通过<code>REGISTER_TILING_DATA_CLASS</code>将默认结构体与算子类型绑定。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">REGISTER_TILING_DATA_CLASS</span><span class="p">(</span><span class="n">AddCustom</span><span class="p">,</span><span class="w"> </span><span class="n">AddStruct</span><span class="p">)</span>
</code></pre></div><p>宏定义结构体的核函数（Kernel）入口不使用<code>REGISTER_TILING_DEFAULT</code>，直接通过构建生成的TilingData访问宏获取数据。</p><p>本节只介绍默认TilingData的注册方式。同一算子需要组织多个核函数（Kernel）分支时，分支专用TilingData的注册方式以及核函数（Kernel）模板参数的配置方式，请参见<a href="./multi_branch_strategy.html">多分支策略</a>。</p><h3 id="获取TilingData">获取TilingData<a class="header-anchor" href="#获取TilingData">​</a></h3><p>核函数（Kernel）可以将入口参数<code>GM_ADDR tiling</code>转换为GM指针，再按照TilingData的内存布局和字段偏移读取数据。但这种写法需要核函数（Kernel）自行维护地址转换和偏移关系，并且会使代码直接依赖动态编译的GM地址和内存布局；静态编译场景仍需单独处理。</p><p><code>GET_TILING_DATA</code>和<code>GET_TILING_DATA_WITH_STRUCT</code>封装了动态、静态两种场景下Tiling数据获取方式的差异。动态编译场景下，宏在核函数（Kernel）运行时从入口参数tiling指向的GM内存读取Tiling数据，并初始化相应的Tiling结构体；静态编译场景下，Host Tiling在算子编译阶段执行，生成的Tiling数据被直接固化到核函数（Kernel）代码中，宏使用这些内嵌数据初始化Tiling结构体，不再访问核函数（Kernel）入口的tiling参数。两种场景使用相同的宏调用和字段访问方式，因此一套核函数（Kernel）代码可以同时支持动态编译和静态编译，实现核函数（Kernel）源码层面的动静归一。</p><p>两个宏的能力区别如下：</p><ul><li><a href="../../../../../api/SIMD-API/basic_api/Kernel-Tiling/GET_TILING_DATA.html">GET_TILING_DATA</a><code>(tiling_data, tiling_arg)</code>：使用当前核函数（Kernel）分支注册的默认TilingData类型进行解析，适用于只需访问默认结构体的场景。</li><li><a href="../../../../../api/SIMD-API/basic_api/Kernel-Tiling/GET_TILING_DATA_WITH_STRUCT.html">GET_TILING_DATA_WITH_STRUCT</a><code>(tiling_struct, tiling_data, tiling_arg)</code>：显式指定解析使用的TilingData结构体类型，既可用于不同TilingKey使用不同结构体的场景，也可用于TPL/SEL模板分支显式指定模板TilingData结构体的场景。</li></ul><p>默认TilingData结构体通过<code>GET_TILING_DATA</code>解析。第一个参数是解析后的变量名，第二个参数是核函数（Kernel）入口中的<code>tiling</code>地址。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">GET_TILING_DATA</span><span class="p">(</span><span class="n">tilingData</span><span class="p">,</span><span class="w"> </span><span class="n">tiling</span><span class="p">);</span>
</code></pre></div><p>解析完成后，核函数（Kernel）侧可以读取<code>tilingData</code>中的字段，例如将<code>totalLength</code>和<code>tileNum</code>传给<code>KernelAdd::Init</code>。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">KernelAdd</span><span class="w"> </span><span class="n">op</span><span class="p">;</span>
<span class="n">op</span><span class="p">.</span><span class="n">Init</span><span class="p">(</span><span class="n">x</span><span class="p">,</span><span class="w"> </span><span class="n">y</span><span class="p">,</span><span class="w"> </span><span class="n">z</span><span class="p">,</span><span class="w"> </span><span class="n">tilingData</span><span class="p">.</span><span class="n">totalLength</span><span class="p">,</span><span class="w"> </span><span class="n">tilingData</span><span class="p">.</span><span class="n">tileNum</span><span class="p">);</span>
</code></pre></div><p>需要显式指定TilingData结构体类型时，通过<code>GET_TILING_DATA_WITH_STRUCT</code>解析：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">GET_TILING_DATA_WITH_STRUCT</span><span class="p">(</span><span class="n">TilingDataTemplate</span><span class="p">,</span><span class="w"> </span><span class="n">tilingData</span><span class="p">,</span><span class="w"> </span><span class="n">tiling</span><span class="p">);</span>
</code></pre></div><p>第一个参数可以是按TilingKey注册的分支专用结构体，也可以是TPL/SEL模板分支使用的模板TilingData结构体。两种分支组织方式的宏调用和字段访问方式相同；分支和结构体的具体配置方式请参见<a href="./multi_branch_strategy.html">多分支策略</a>。使用默认结构体的分支仍通过<code>GET_TILING_DATA</code>解析。</p><p>TilingData定义方式和Host侧写入流程请参考<a href="./host_tiling_implementation.html">Host侧Tiling实现</a>。</p><h2 id="信息获取">信息获取<a class="header-anchor" href="#信息获取">​</a></h2><p>核函数（Kernel）侧除了输入输出地址和TilingData，还可以通过框架生成的宏获取输入输出的dtype和format信息。这些信息通常用于为GlobalTensor、LocalTensor等对象指定元素数据类型，选择计算路径或处理format差异。</p><h3 id="获取输入输出dtype和format">获取输入输出dtype和format<a class="header-anchor" href="#获取输入输出dtype和format">​</a></h3><p>核函数（Kernel）侧可以通过<code>DTYPE_&lt;Arg&gt;</code>、<code>ORIG_DTYPE_&lt;Arg&gt;</code>、<code>FORMAT_&lt;Arg&gt;</code>三类宏获取输入输出的数据类型和格式信息。<code>&lt;Arg&gt;</code>由核函数（Kernel）入口参数名转换成全大写形式。</p><table><thead><tr><th>原型定义name</th><th>核函数（Kernel）入口参数名</th><th>dtype宏</th><th>原始dtype宏</th><th>format宏</th></tr></thead><tbody><tr><td><code>x</code></td><td><code>x</code></td><td><code>DTYPE_X</code></td><td><code>ORIG_DTYPE_X</code></td><td><code>FORMAT_X</code></td></tr><tr><td><code>y</code></td><td><code>y</code></td><td><code>DTYPE_Y</code></td><td><code>ORIG_DTYPE_Y</code></td><td><code>FORMAT_Y</code></td></tr><tr><td><code>z</code></td><td><code>z</code></td><td><code>DTYPE_Z</code></td><td><code>ORIG_DTYPE_Z</code></td><td><code>FORMAT_Z</code></td></tr><tr><td><code>input_data</code></td><td><code>input_data</code></td><td><code>DTYPE_INPUT_DATA</code></td><td><code>ORIG_DTYPE_INPUT_DATA</code></td><td><code>FORMAT_INPUT_DATA</code></td></tr><tr><td><code>output_result</code></td><td><code>output_result</code></td><td><code>DTYPE_OUTPUT_RESULT</code></td><td><code>ORIG_DTYPE_OUTPUT_RESULT</code></td><td><code>FORMAT_OUTPUT_RESULT</code></td></tr></tbody></table><p>三类宏的含义如下：</p><table><thead><tr><th>宏</th><th>含义</th><th>常见用途</th></tr></thead><tbody><tr><td><code>DTYPE_&lt;Arg&gt;</code></td><td>核函数（Kernel）侧可直接使用的C++数据类型，如<code>half</code>、<code>float</code>、<code>int32_t</code></td><td>声明变量、<code>GlobalTensor</code>、<code>LocalTensor</code>或模板参数</td></tr><tr><td><code>ORIG_DTYPE_&lt;Arg&gt;</code></td><td>算子原型中声明的dtype编号，如<code>DT_FLOAT16</code>、<code>DT_FLOAT</code></td><td>与dtype编号比较，选择不同计算路径</td></tr><tr><td><code>FORMAT_&lt;Arg&gt;</code></td><td>算子原型中声明的format编号，如<code>FORMAT_ND</code>、<code>FORMAT_NZ</code></td><td>根据format选择不同数据组织方式</td></tr></tbody></table><p><code>DTYPE_X</code>和<code>ORIG_DTYPE_X</code>关注点不同。以<code>x</code>为例，<code>DTYPE_X</code>可以直接作为核函数（Kernel）侧C++类型使用；<code>ORIG_DTYPE_X</code>用于和dtype编号比较。<code>ORIG_DTYPE_&lt;Arg&gt;</code>和<code>FORMAT_&lt;Arg&gt;</code>由编译选项传入，通常用于预处理分支。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">extern</span><span class="w"> </span><span class="s">&quot;C&quot;</span><span class="w"> </span><span class="n">__global__</span><span class="w"> </span><span class="n">__aicore__</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">add_custom</span><span class="p">(</span><span class="n">GM_ADDR</span><span class="w"> </span><span class="n">x</span><span class="p">,</span><span class="w"> </span><span class="n">GM_ADDR</span><span class="w"> </span><span class="n">y</span><span class="p">,</span><span class="w"> </span><span class="n">GM_ADDR</span><span class="w"> </span><span class="n">z</span><span class="p">,</span>
<span class="w">                                                  </span><span class="n">GM_ADDR</span><span class="w"> </span><span class="n">workspace</span><span class="p">,</span><span class="w"> </span><span class="n">GM_ADDR</span><span class="w"> </span><span class="n">tiling</span><span class="p">)</span>
<span class="p">{</span>
<span class="w">    </span><span class="n">GET_TILING_DATA</span><span class="p">(</span><span class="n">tilingData</span><span class="p">,</span><span class="w"> </span><span class="n">tiling</span><span class="p">);</span>

<span class="w">    </span><span class="n">DTYPE_X</span><span class="w"> </span><span class="n">temp</span><span class="p">;</span>
<span class="w">    </span><span class="n">func</span><span class="o">&lt;</span><span class="n">DTYPE_Z</span><span class="o">&gt;</span><span class="p">();</span>

<span class="w">    </span><span class="cp">#if FORMAT_Y == FORMAT_ND</span>
<span class="w">    </span><span class="c1">// ND格式处理逻辑</span>
<span class="w">    </span><span class="cp">#endif</span>

<span class="w">    </span><span class="cp">#if ORIG_DTYPE_Y == DT_FLOAT</span>
<span class="w">    </span><span class="c1">// float类型处理逻辑</span>
<span class="w">    </span><span class="cp">#endif</span>
<span class="p">}</span>
</code></pre></div><div class="callout callout-note"><p class="callout-title"><svg class="callout-icon" viewBox="0 0 16 16" width="16" height="16"><path d="M0 8a8 8 0 1 1 16 0A8 8 0 0 1 0 8Zm8-6.5a6.5 6.5 0 1 0 0 13 6.5 6.5 0 0 0 0-13ZM6.5 7.75A.75.75 0 0 1 7.25 7h1a.75.75 0 0 1 .75.75v2.75h.25a.75.75 0 0 1 0 1.5h-2a.75.75 0 0 1 0-1.5h.25v-2h-.25a.75.75 0 0 1-.75-.75ZM8 6a1 1 0 1 1 0-2 1 1 0 0 1 0 2Z"></path></svg>核函数（Kernel）模板场景下的宏使用</p><p>在核函数（Kernel）模板场景中，应谨慎使用<code>DTYPE_&lt;Arg&gt;</code>、<code>ORIG_DTYPE_&lt;Arg&gt;</code>和<code>FORMAT_&lt;Arg&gt;</code>等宏配合<code>#if/#endif</code>分割代码。预处理宏和模板实例化都会影响最终生成的代码；若同时使用，需要检查每个模板参数组合下的宏取值、保留的代码分支和模板实参是否一致，避免宏裁剪掉某个模板实例所需的代码，或产生重复定义、符号冲突等问题。由模板参数决定的分支，建议优先使用<code>if constexpr</code>表达。</p></div><h2 id="相关文档">相关文档<a class="header-anchor" href="#相关文档">​</a></h2><ul><li><a href="./host_tiling_implementation.html">Host侧Tiling实现</a>：了解TilingData定义、Tiling函数编写和workspace设置。</li><li><a href="./operator_prototype_definition.html">算子原型定义</a>：了解输入输出顺序、dtype/format声明和AI处理器配置。</li><li><a href="./multi_branch_strategy.html">多分支策略</a>：了解<code>TilingKey</code>如何选择不同核函数（Kernel）实现分支。</li><li><a href="./kernel_output_shape_computation.html">输出shape依赖计算</a>：了解输出shape依赖核函数（Kernel）计算结果时的处理方式。</li></ul></article></div>`,1)])])}const g=a(c,[["render",e]]);export{h as __pageData,g as default};
